dtsPropsFor.AuthShell:
title: React.ReactNode;
  subtitle?: React.ReactNode;
  children?: React.ReactNode;
  /** Bottom slot (secondary links). */
  footer?: React.ReactNode;
  /** Route path for the back chevron (router Link; needs DsProvider). */
  backTo?: string;
  /** max-w-lg instead of max-w-sm. */
  wide?: boolean;
  /** TourShop logo above the title. Default true. */
  showLogo?: boolean;

dtsPropsFor.BottomSheet:
/** Renders nothing when false. Portals into #modal-root (DsProvider). */
  open: boolean;
  onClose: () => void;
  title: React.ReactNode;
  description?: React.ReactNode;
  children?: React.ReactNode;
  /** Sticky footer (action buttons). */
  footer?: React.ReactNode;

dtsPropsFor.TopBar:
title: React.ReactNode;
  subtitle?: React.ReactNode;
  /** Back chevron (needs DsProvider). */
  back?: boolean;
  right?: React.ReactNode;

dtsPropsFor.StickyActionBar:
/** Buttons laid out in a row (flex gap-2). */
  children: React.ReactNode;
  /** Small centered line above the buttons. */
  hint?: React.ReactNode;

dtsPropsFor.EmptyState:
icon?: React.ComponentType<{ size?: number; className?: string }>;
  title: React.ReactNode;
  description?: React.ReactNode;
  action?: React.ReactNode;
  /** Icon tile color. Default 'default' (primary). */
  tone?: 'default' | 'success' | 'warning' | 'error';
  /** Less vertical padding. */
  compact?: boolean;

dtsPropsFor.StatCard:
icon?: React.ComponentType<{ size?: number; className?: string }>;
  label: React.ReactNode;
  value: React.ReactNode;
  hint?: React.ReactNode;
  /** Icon tile color. Default 'primary'. */
  tone?: 'primary' | 'accent' | 'success' | 'warning' | 'neutral';
  /** Makes the card a router link (needs DsProvider). */
  to?: string;

dtsPropsFor.FormField:
label?: React.ReactNode;
  htmlFor?: string;
  /** Replaces the hint with a red error line. */
  error?: React.ReactNode;
  hint?: React.ReactNode;
  /** The control (e.g. <input className="input-field" />, PasswordInput, PhoneInput). */
  children: React.ReactNode;
  /** Appends "(facultatif)" to the label. */
  optional?: boolean;
  className?: string;

dtsPropsFor.PasswordInput:
/** All <input> props pass through; renders an input-field with a show/hide toggle. */
  id?: string;
  name?: string;
  value?: string;
  placeholder?: string;
  autoComplete?: string;
  onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void;
  className?: string;

dtsPropsFor.PhoneInput:
id?: string;
  /** ISO country code; defaults to CI. */
  country?: string;
  onCountryChange?: (code: string) => void;
  /** National number. */
  value: string;
  onChange: (value: string) => void;
  invalid?: boolean;
  /** Disable the country picker. */
  lockCountry?: boolean;
  /** "Numéro national : …" hint. Default true. */
  showHint?: boolean;

dtsPropsFor.CodeInput:
/** Number of digit boxes. Default 4. */
  length?: number;
  value: string;
  onChange: (value: string) => void;
  autoFocus?: boolean;
  invalid?: boolean;
  /** Accessible group label. */
  label?: string;

dtsPropsFor.FilePicker:
/** Selected image; shows a preview with a remove button. */
  value: File | null;
  onChange: (file: File | null) => void;
  label?: string;
  /** Camera capture hint ('environment' | 'user'). */
  capture?: 'environment' | 'user';
  id?: string;
  invalid?: boolean;

dtsPropsFor.SignaturePad:
/** Receives a PNG data URL after each stroke, null when cleared. */
  onChange?: (dataUrl: string | null) => void;
  /** Placeholder shown while empty. */
  label?: string;

dtsPropsFor.FilterChips:
options: { key: string; label: React.ReactNode; count?: number }[];
  value: string;
  onChange: (key: string) => void;
  className?: string;

dtsPropsFor.SegmentedTabs:
tabs: { key: string; label: React.ReactNode; count?: number }[];
  value: string;
  onChange: (key: string) => void;

dtsPropsFor.CountrySelectSheet:
open: boolean;
  onClose: () => void;
  currentCode?: string;
  onSelect: (country: { code: string; nom: string; indicatif: string; flag: string }) => void;
  title?: string;
  description?: React.ReactNode;

dtsPropsFor.StatusBadge:
label: React.ReactNode;
  /** 'active' pulses (accent orange). Default 'neutral'. */
  tone?: 'info' | 'active' | 'waiting' | 'success' | 'danger' | 'neutral';
  className?: string;

dtsPropsFor.ExpeditionStatusBadge:
/** Workflow phase of an expedition mission. */
  phase: 'offer' | 'start' | 'pickup' | 'deposit' | 'deliver' | 'done' | 'cancelled';
  className?: string;

dtsPropsFor.MissionCard:
/** Assigned expedition mission (API shape). Phase and route are derived from it. Needs DsProvider (renders a Link). */
  mission: {
    id: string | number;
    type: 'enlevement' | 'livraison';
    mode: 'express' | 'groupage';
    statut: 'en_attente' | 'assignee' | 'terminee' | 'annulee';
    montant_final?: number;
    assignee_le?: string;
    expedition?: {
      reference?: string;
      statut_expedition?: string;
      date_enlevement_client?: string;
      expediteur?: { nom_prenom?: string; telephone?: string; adresse?: string; quartier?: string; ville?: string };
      destinataire?: { nom_prenom?: string; telephone?: string; adresse?: string; quartier?: string; ville?: string };
      agence?: { nom?: string; adresse?: string; ville?: string };
    };
  };

dtsPropsFor.MissionStepper:
/** e.g. EXPEDITION_STEPS.enlevement, EXPEDITION_STEPS.livraison, MARKETPLACE_STEPS (exported). */
  steps: { key: string; label: string }[];
  /** Index of the last completed step; the next one is highlighted as in progress. */
  current: number;

dtsPropsFor.OfferCard:
/** 'marketplace' = green bag icon, 'express' = orange bolt. Default 'express'. */
  kind?: 'express' | 'marketplace';
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  route?: { from: { label: string; title?: string; detail?: string }; to: { label: string; title?: string; detail?: string } };
  /** Small facts row (weight, distance…). */
  meta?: React.ReactNode;
  /** Amount already offered (FCFA); switches to "Offre envoyée" + Modifier. */
  myOffer?: number | null;
  onOffer?: () => void;
  disabled?: boolean;
  disabledReason?: React.ReactNode;

dtsPropsFor.OfferSheet:
open: boolean;
  onClose: () => void;
  title: React.ReactNode;
  description?: React.ReactNode;
  /** Prefills the amount; enables update/withdraw. */
  currentOffer?: number | null;
  onSubmit: (montant: number) => void;
  onWithdraw?: () => void;
  loading?: boolean;
  /** Info note under the amount. */
  note?: React.ReactNode;

dtsPropsFor.ConfirmSheet:
open: boolean;
  onClose: () => void;
  onConfirm: () => void;
  loading?: boolean;
  title: React.ReactNode;
  description?: React.ReactNode;
  confirmLabel: React.ReactNode;
  children?: React.ReactNode;
  error?: React.ReactNode;

dtsPropsFor.ContactCard:
/** Uppercase caption, e.g. "Expéditeur". */
  role: React.ReactNode;
  /** Renders nothing when null. Phone/address enable the call, SMS and route actions. */
  contact: { nom?: string; telephone?: string; adresse?: string; quartier?: string; ville?: string; lat?: number; lng?: number } | null;
  /** Accent ring (current step's contact). */
  highlight?: boolean;
  /** Building icon instead of a person. */
  isAgency?: boolean;

dtsPropsFor.MarketplaceCard:
/** Assigned marketplace delivery (API shape). Needs DsProvider (renders a Link). */
  livraison: {
    id: string | number;
    mode: 'direct' | 'reseau';
    statut: 'en_attente' | 'assignee' | 'en_cours' | 'terminee' | 'livree' | 'annulee';
    montant_final?: number;
    assignee_le?: string;
    commande?: { id?: string | number; montant_articles?: number };
  };

dtsPropsFor.QuickActionsRow:
/** Adds Appeler (tel:) and SMS (sms:) buttons. */
  phone?: string;
  /** Adds an Itinéraire button. Renders nothing when both are missing. */
  mapsUrl?: string;

dtsPropsFor.RouteLine:
from: { label: string; title?: string; detail?: string };
  to: { label: string; title?: string; detail?: string };
  /** Smaller text, hides details. */
  compact?: boolean;
